/* ==========================================================================
   Inline Layout: Quantity + Equal Width Add to Cart & Wish List
   ========================================================================== */

/* Outer Row Container holding both forms */
.action-row-container {
    display: grid !important;
    grid-template-columns: min-content 1fr 1fr !important; /* Quantity auto-fit | Equal Button 1 | Equal Button 2 */
    align-items: end !important;                            /* Bottom baseline alignment */
    gap: 12px !important;
    width: 100% !important;
    margin-top: 15px !important;
    margin-bottom: 15px !important;
    clear: both !important;
}

/* 1. Un-restrict Cart Form so buttons share equal grid tracks */
.action-row-container > form[data-cart-item-add] {
    display: contents !important;                           /* Unwraps Form 1 so items fill grid tracks directly */
}

/* Product Options full-width row inside Form 1 */
.action-row-container .product-variants {
    grid-column: 1 / -1 !important;                         /* Spans full width above action row */
    width: 100% !important;
}

/* Stock field full width if present */
.action-row-container .form-field--stock {
    grid-column: 1 / -1 !important;
}

/* 2. Unwrap #add-to-cart-wrapper component */
.action-row-container #add-to-cart-wrapper {
    display: contents !important;
}

/* Column 1: Quantity Field */
.action-row-container .form-field--increments {
    grid-column: 1 !important;
    margin: 0 !important;
    width: min-content !important;
    white-space: nowrap !important;
}

/* Column 2: Add to Cart Button Container (Exact 1fr) */
.action-row-container .add-to-cart-buttons {
    grid-column: 2 !important;
    margin: 0 !important;
    width: 100% !important;
}

/* Column 3: Wish List Form Container (Exact 1fr) */
.action-row-container .form-wishlist {
    grid-column: 3 !important;
    margin: 0 !important;
    width: 100% !important;
    position: relative !important;
}

/* ==========================================================================
   Button Specific Styling (Identical 1:1 Equal Width & Height)
   ========================================================================== */
#form-action-addToCart,
.action-row-container .wishlist-button {
    width: 100% !important;
    height: 46px !important;
    margin: 0 !important;
    padding: 0 10px !important;
    
    font-size: 16px !important;
    font-weight: 600 !important;
    box-sizing: border-box !important;
    
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
    white-space: nowrap !important;
    vertical-align: bottom !important;
}

/* Wish List Inner Text Formatting */
.action-row-container .wishlist-button span {
    white-space: nowrap !important;
    overflow: hidden !important;
    text-overflow: ellipsis !important;
    font-size: 16px !important;
    font-weight: 600 !important;
}

/* Wish List Arrow Icon Alignment */
.action-row-container .wishlist-button .icon {
    margin-left: 6px !important;
    flex-shrink: 0 !important;
    display: inline-flex !important;
    align-items: center !important;
}

/* Wishlist Dropdown Popup Layering */
.action-row-container .dropdown-menu {
    z-index: 99 !important;
}

/* ==========================================================================
   TARGETED FIX FOR: iPhone SE, iPad Mini, iPad Air (Screen Widths <= 991px)
   ========================================================================== */
/* ==========================================================================
   STRICT MOBILE & TABLET FIX (Quantity Top | Buttons Side-by-Side 50/50)
   ========================================================================== */
@media screen and (max-width: 991px) {
    /* 1. Main Container Flex Wrap */
    .action-row-container {
        display: flex !important;
        flex-wrap: wrap !important;
        gap: 10px !important;
        width: 100% !important;
    }

    /* 2. Cart Form Container Flex (Prevents form from taking separate line) */
    .action-row-container > form[data-cart-item-add] {
        display: flex !important;
        flex-wrap: wrap !important;
        width: 100% !important;
        flex: 1 1 100% !important;
        margin: 0 !important;
    }

    /* 3. Inner Add to Cart Wrapper */
    .action-row-container #add-to-cart-wrapper {
        display: flex !important;
        flex-wrap: wrap !important;
        gap: 10px !important;
        width: 100% !important;
        margin: 0 !important;
    }

    /* 4. Quantity Box (Takes Full Width on Top Row) */
    .action-row-container .form-field--increments {
        width: 100% !important;
        flex: 1 1 100% !important;
        margin-bottom: 4px !important;
    }

    /* 5. Add to Cart Button (Left 50% Share) */
    .action-row-container .add-to-cart-buttons {
