        flex: 1 1 calc(50% - 5px) !important;
        min-width: 0 !important;
        margin: 0 !important;
    }

    /* 7. Button Height & Styling Fix */
    #form-action-addToCart,
    .action-row-container .wishlist-button {
        width: 100% !important;
        height: 44px !important;
        margin: 0 !important;
        padding: 0 4px !important;
